    (15841,'','The Cataclysm has destroyed the western mountains of Thousand Needles. The South Sea has rushed in and the canyons are flooded.$B$BPlease, $c, you must come to our aid at New Thalanaar!',0,1,0,5,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,0),
